kube-controller-manager.pseudocode:
def reconcile(controller, api):
    while True:
        # Watch로 관련 리소스 변경 수신
        event = api.watch(controller.resource)
        desired = event.spec  # 선언된 원하는 상태
        current = api.get_status(event.name)  # 현재 상태
        if current != desired:
            # 차이를 해소하도록 API 서버에 변경 요청
            diff = compute_diff(current, desired)
            api.apply(diff)

kube-scheduler.pseudocode:
def schedule(pod, nodes):
    # 1단계: 필터링(실행 불가 노드 제외)
    feasible = []
    for n in nodes:
        if fits_resources(pod, n) and \
           tolerates(pod, n) and affinity_ok(pod, n):
            feasible.append(n)
    if not feasible:
        return None  # 스케줄 불가(Pending)
    # 2단계: 스코어링(적합도 최고 노드 선택)
    best, best_score = None, -1
    for n in feasible:
        s = score(pod, n)  # 0~100
        if s > best_score:
            best, best_score = n, s
    return best  # 바인딩 대상
